<script>
const ASSETS = {
    characters: {},
    backgrounds: {},
    bgm: {}
};
/**
 * Resolves a keyword or raw URL to a full URL.
 * If the value is already a URL (starts with http), return as-is.
 * Otherwise look it up in the ASSETS table.
 */
function normalizeAssetKey(key) {
    return String(key || '').toLowerCase().replace(/[^a-z0-9]+/g, '');
}

function pickRandomAssetUrl(value) {
    if (Array.isArray(value)) {
        const filtered = value.filter(Boolean);
        if (filtered.length === 0) return null;
        return filtered[Math.floor(Math.random() * filtered.length)];
    }
    return value || null;
}

const CHARACTER_FALLBACK_DEFAULTS = {};

function resolveCharacterSprite(key) {
    if (!key) return null;
    const trimmed = String(key).trim();
    if (!trimmed) return null;
    if (trimmed.startsWith('http')) return trimmed;

    if (ASSETS.characters[trimmed]) return ASSETS.characters[trimmed];

    const normalized = normalizeAssetKey(trimmed);
    if (ASSETS.characters[normalized]) return ASSETS.characters[normalized];

    for (const [needle, fallbackKey] of Object.entries(CHARACTER_FALLBACK_DEFAULTS)) {
        if (normalized.includes(needle)) {
            return ASSETS.characters[fallbackKey] || null;
        }
    }
    return null;
}

/**
 * Resolves a keyword or raw URL to a full URL.
 * If the value is already a URL (starts with http), return as-is.
 * Otherwise look it up in the ASSETS table.
 */
function resolveAsset(table, key) {
    if (!key) return null;
    const trimmed = String(key).trim();
    if (!trimmed) return null;
    if (trimmed.startsWith('http')) return trimmed;
    if (table === 'characters') return resolveCharacterSprite(trimmed);

    const tableValue = ASSETS[table] ? ASSETS[table][trimmed] : undefined;
    if (Array.isArray(tableValue)) return pickRandomAssetUrl(tableValue);
    return tableValue || trimmed;
}

</script>

<script>
function parseGameData(text) {
    const scenesData = text.trim().split(/\n---\n/);
    const scenes = [];
    let lastValidSceneData = {};

    scenesData.forEach(sceneText => {
        if (!sceneText.trim()) return;
        const lines = sceneText.trim().split('\n');
        const scene = {
            id: scenes.length, dialogues: [], choices: [], characters: [],
            audio: {}, is_cg_mode: false, cg_image: null,
        };
        let inPhoneBlock = false, inCgBlock = false, isParsingMemo = false;
        let currentPhoneData = null, currentContact = null;

        for (const line of lines) {
            const trimmedLine = line.trim();
            if (trimmedLine === '[CG]') { inCgBlock = true; scene.is_cg_mode = true; continue; }
            if (trimmedLine === '[/CG]') { inCgBlock = false; continue; }
            if (trimmedLine === '[PHONE]') {
                inPhoneBlock = true; currentPhoneData = { memos: '', contacts: [] }; continue;
            }
            if (trimmedLine === '[/PHONE]') {
                inPhoneBlock = false;
                if (currentPhoneData) {
                    scene.dialogues.push({ type: 'action', command: 'SHOW_PHONE', phone_data: currentPhoneData, id: `s${scene.id}-act${scene.dialogues.length}` });
                    currentPhoneData = null;
                }
                continue;
            }

            if (inPhoneBlock) {
                if (trimmedLine.startsWith('@memo:')) {
                    isParsingMemo = true; currentPhoneData.memos = '';
                    const memoTitle = trimmedLine.substring(6).trim();
                    if (memoTitle) currentPhoneData.memos += memoTitle + '\n';
                    continue;
                }
                if (trimmedLine.startsWith('@contact:')) {
                    isParsingMemo = false;
                    const [name, avatar] = trimmedLine.substring(9).split(',').map(s => s.trim());
                    currentContact = { name, avatar, messages: [] };
                    currentPhoneData.contacts.push(currentContact);
                    continue;
                }
                if (isParsingMemo) {
                    currentPhoneData.memos += (currentPhoneData.memos ? '\n' : '') + trimmedLine; continue;
                }
                if (trimmedLine.startsWith('R:') && currentContact) { currentContact.messages.push({ type: 'received', text: trimmedLine.substring(2).trim() }); continue; }
                if (trimmedLine.startsWith('S:') && currentContact) { currentContact.messages.push({ type: 'sent', text: trimmedLine.substring(2).trim() }); continue; }
                continue;
            }

            if (trimmedLine.startsWith('@bg:')) { scene.bg_image = resolveAsset('backgrounds', trimmedLine.substring(4).trim()); continue; }
            if (trimmedLine.startsWith('@cg_image:')) { scene.cg_image = trimmedLine.substring(10).trim(); continue; }
            if (trimmedLine.startsWith('@location:')) { scene.status_location = trimmedLine.substring(10).trim(); continue; }
            if (trimmedLine.startsWith('@time:')) { scene.status_time = trimmedLine.substring(6).trim(); continue; }
            if (trimmedLine.startsWith('@bgm:')) { scene.audio.bgm = trimmedLine.substring(5).trim(); continue; }
            if (trimmedLine.startsWith('* ')) {
                const [label, action] = trimmedLine.substring(2).split('->').map(s => s.trim());
                scene.choices.push({ label, action }); continue;
            }
            if (trimmedLine.startsWith('@input:')) { scene.custom_input_placeholder = trimmedLine.substring(7).trim(); continue; }
            if (trimmedLine.startsWith('@status:')) {
                const [name, affection, avatarRaw] = trimmedLine.substring(8).split(',').map(s => s.trim());
                const avatar = resolveAsset('characters', avatarRaw);
                scene.characters.push({ name, affection: parseInt(affection), avatar }); continue;
            }

            const dialogueMatch = trimmedLine.match(/^([^>]+)>\s*(.*)/);
            if (dialogueMatch) {
                let speaker = dialogueMatch[1].trim();
                const text = dialogueMatch[2].trim();
                let spriteInfo = null;

                if (speaker.toLowerCase() !== '旁白') {
                    const spriteMatch = speaker.match(/^(.*?)\(([^)]*)\)$/);
                    if (spriteMatch && !inCgBlock) {
                        speaker = spriteMatch[1].trim();
                        const params = spriteMatch[2].split(',').map(p => p.trim());
                        spriteInfo = {
                            url: resolveAsset('characters', params[0]) || null,
                            position: params[1] || 'center',
                            status: params[2] || 'silent',
                            scale: parseFloat(params[3]) || 1.0
                        };
                    }
                }
                scene.dialogues.push({
                    type: 'dialogue', speaker: speaker, text: text, sprite: spriteInfo,
                    is_narrator: speaker.toLowerCase() === '旁白', id: `s${scene.id}-d${scene.dialogues.length}`
                });
                continue;
            }
        }

        scene.bg_image = scene.bg_image !== undefined ? scene.bg_image : lastValidSceneData.bg_image;
        scene.cg_image = scene.cg_image !== undefined ? scene.cg_image : lastValidSceneData.cg_image;
        scene.is_cg_mode = scene.is_cg_mode !== undefined ? scene.is_cg_mode : lastValidSceneData.is_cg_mode;
        scene.status_location = scene.status_location || lastValidSceneData.status_location;
        scene.status_time = scene.status_time || lastValidSceneData.status_time;
        if (scene.characters.length === 0 && lastValidSceneData.characters) {
            scene.characters = lastValidSceneData.characters;
        }
        scenes.push(scene);
        lastValidSceneData = JSON.parse(JSON.stringify(scene));
    });
    return { scenes, audio: { sfx: { click: "https://s3plus.meituan.net/opapisdk/op_ticket_1_885190757_1780574421593_gwWljbcb.m4a", confirm: "https://files.catbox.moe/agwxnc.mp3" } } };
}

