    function renderSpriteForDialogue(dialogue) {
        const spriteInfo = dialogue.sprite;
        if (dialogue.is_narrator || !spriteInfo || !spriteInfo.url) {
            Object.values(activeSprites).forEach(sprite => { if (sprite) { sprite.classList.remove('speaking'); sprite.classList.add('silent'); }});
            return;
        }
        const { url, position, status, scale } = spriteInfo;
        if (position === 'center') { clearSprite('left'); clearSprite('right'); }
        else if (position === 'left' || position === 'right') { clearSprite('center'); }
        Object.keys(activeSprites).forEach(pos => { if (pos !== position && activeSprites[pos]) { activeSprites[pos].classList.remove('speaking'); activeSprites[pos].classList.add('silent'); }});
        const slot = spriteSlots[position]; if (!slot) return;
        const existingSprite = activeSprites[position];

        if (existingSprite && existingSprite.src.includes(new URL(url, location.href).pathname)) {
            existingSprite.classList.remove('speaking', 'silent');
            existingSprite.classList.add(status);
            existingSprite.style.setProperty('--individual-sprite-scale', scale);
        } else {
            clearSprite(position);
            const spriteImg = document.createElement('img');
            spriteImg.src = url; spriteImg.className = 'character-sprite'; spriteImg.classList.add(status);
            spriteImg.style.setProperty('--individual-sprite-scale', scale); spriteImg.style.opacity = '0';
