        } else {
            const scene = scenes[currentSceneIndex]; const dialogues = scene.dialogues || [];
            if (currentDialogueIndex >= dialogues.length) {
                nameTag.textContent = ''; textContentEl.textContent = ''; continueBtn.style.display = 'none'; backBtn.style.display = 'none';
                dialogueBox.classList.remove('hidden'); showChoices(); return;
