    function isTextOverflowing(text, element) {
        const tempEl = document.createElement('div');
        tempEl.style.position = 'absolute'; tempEl.style.visibility = 'hidden'; tempEl.style.height = 'auto';
        tempEl.style.width = element.clientWidth + 'px'; tempEl.style.fontSize = getComputedStyle(element).fontSize;
        tempEl.style.fontFamily = getComputedStyle(element).fontFamily;
        tempEl.style.lineHeight = getComputedStyle(element).lineHeight;
        tempEl.style.webkitBoxOrient = 'vertical'; tempEl.style.display = '-webkit-box'; tempEl.style.webkitLineClamp = '5';
            tempEl.style.overflow = 'hidden';
        tempEl.textContent = text; document.body.appendChild(tempEl);
        const isOverflowing = tempEl.scrollHeight > tempEl.clientHeight; document.body.removeChild(tempEl);
        return isOverflowing;
    }
    function segmentText(text) {
        if (!text) return ['']; const segments = []; let remainingText = text;
        const tempEl = document.createElement('div');
        tempEl.style.position = 'absolute'; tempEl.style.visibility = 'hidden'; tempEl.style.height = 'auto';
        tempEl.style.width = textContentEl.clientWidth + 'px'; tempEl.style.fontSize = getComputedStyle(textContentEl).fontSize;
        tempEl.style.fontFamily = getComputedStyle(textContentEl).fontFamily;
        tempEl.style.lineHeight = getComputedStyle(textContentEl).lineHeight;
        tempEl.style.webkitBoxOrient = 'vertical'; tempEl.style.display = '-webkit-box'; tempEl.style.webkitLineClamp = '5';
            tempEl.style.overflow = 'hidden';
        document.body.appendChild(tempEl);
        while (remainingText.length > 0) {
            let low = 0, high = remainingText.length, cutIndex = 0;
            while(low <= high) {
                let mid = Math.floor((low + high) / 2);
                tempEl.textContent = remainingText.substring(0, mid);
                if (tempEl.scrollHeight <= tempEl.clientHeight) { cutIndex = mid; low = mid + 1; } else { high = mid - 1; }
            }
            segments.push(remainingText.substring(0, cutIndex)); remainingText = remainingText.substring(cutIndex);
        }
        document.body.removeChild(tempEl); return segments.length > 0 ? segments : [''];
    }

    function renderCurrentDialogueState() {
        const scene = scenes[currentSceneIndex];
        if (!scene) return;
        const dialogues = scene.dialogues || [];
        const dialogue = dialogues[currentDialogueIndex];
